	__size = 897,
	[101] = {
		talkContent_th = "“การต่อสู้ของลีกนั้นดุเดือดและน่าตื่นเต้น และในที่สุดเราก็กำลังจะเข้าสู่การต่อสู้ครั้งสุดท้าย ขอต้อนรับผู้ฝึกสอนสองคนที่ต่อสู้อย่างเต็มที่จนถึงการต่อสู้อันรุ่งโรจน์ในรอบชิงชนะเลิศ!”",
		lastTime = 2000,
		roleName_th = "Game Host",
		talkContent_en = "The battles of the League Conference are fierce and exciting, and we are finally about to enter the final battle. Let's welcome the two trainers who fought all the way to a glorious battle in the finals!",
		roleName = "Game Host",
		roleName_en = "Game Host",
		talkContent_id = " Pertarungan Konferensi Liga sangat sengit dan seru, dan akhirnya kita akan memasuki pertarungan final. Mari kita sambut dua trainer yang berjuang hingga pertarungan gemilang di final!",
		id = 101,
		talkContent = "The battles of the League Conference are fierce and exciting, and we are finally about to enter the final battle. Let's welcome the two trainers who fought all the way to a glorious battle in the finals!"
	},
