		talkContent_th = "ยินดีต้อนรับสู่การถ่ายทอดสดการแข่งขันชิงแชมป์โลกที่จัดโดยPokémon League ฉันเป็นเจ้าภาพ Mega  Ampharos ! เช่นเคย ก่อนที่เราจะเริ่มต้นการแข่งขัน ให้เราเชิญผู้ถือคบเพลิงของเรา-  Charizard ! \"",
		needAutoJump = 1,
		id = 816,
		talkContent = "Welcome to the live broadcast of the World Championship hosted by Pokémon League, I am the host, Mega Ampharos! As usual, before the we start the tournament, let us invite our torchbearer-Charizard!   \"",
