	[826] = {
		lastTime = 6000,
		needAutoJump = 1,
		triggerTime = 27000,
		unitId = 10263,
		talkContent_en = " After listening to the pledge taken by the trainers, I am looking forward to this tournament even more. Now that all trainers are ready, I shall announce that the tournament has officially started! \"\"",
		id = 826,
		talkContent_th = "“” หลังจากฟังคำมั่นสัญญาจากผู้ฝึกสอน ผมตั้งตารอการแข่งขันครั้งนี้มากยิ่งขึ้น เมื่อผู้ฝึกสอนทุกคนพร้อมแล้ว ผมจะประกาศว่าการแข่งขันได้เริ่มต้นขึ้นอย่างเป็นทางการแล้ว! \"\"",
		talkContent_id = " Setelah mendengarkan janji yang diucapkan oleh para Trainer, saya semakin menantikan turnamen ini. Sekarang semua trainer sudah siap, saya akan mengumumkan bahwa turnamen telah resmi dimulai! \"\"",
		force = 2,
		talkContent = " After listening to the pledge taken by the trainers, I am looking forward to this tournament even more. Now that all trainers are ready, I shall announce that the tournament has officially started! \"\""
	},
	[850] = {
		lastTime = 4500,
		talkContent_en = "Wow, what an exciting World Championship!   Now I would like to invite the champion of this World Championship, the representative of all Pokémon trainers - Ash of Pallet Town, to say a few words on the torch podium!\" nAsh… My name!\"",
		talkContent_th = "ว้าว ช่างเป็นการแข่งขันชิงแชมป์โลกที่น่าตื่นเต้นจริงๆ! ตอนนี้ฉันอยากจะเชิญแชมป์ของการแข่งขันชิงแชมป์โลกนี้ ตัวแทนของผู้ฝึกโปเกมอนทุกคน - Ash of Pallet Town พูดสักสองสามคำบนแท่นคบเพลิง!\" nAsh… ฉันชื่อ!\"",
		unitId = 10131,
		id = 850,
		talkContent = "Wow, what an exciting World Championship!   Now I would like to invite the champion of this World Championship, the representative of all Pokémon trainers - Ash of Pallet Town, to say a few words on the torch podium!\" nAsh… My name!\"",
		talkContent_id = " Wow, Kejuaraan Dunia yang seru! Sekarang saya ingin mengundang juara Kejuaraan Dunia ini, perwakilan dari semua trainer Pokémon - Ash of Pallet Town, untuk mengucapkan beberapa patah kata di podium obor!\" nAsh… Nama saya!\""
	},
