	[100001] = {
		id = 100001,
		lastTime = 2000,
		talkContent_th = "สวนพฤกษศาสตร์เต็มไปด้วยพืชพันธุ์แปลก ๆ และใบไม้ที่เขียวชอุ่มช่วยบังแสงแดด ตามทางเดินของสวนพฤษศาสตร์ มาถึงบริเวณที่แบ่งเป็นสองทาง ทอดยาวไปสู่ป่าทึบ...",
		talkContent_id = " Kebun raya penuh dengan tanaman asing, dan dedaunan rimbun menutupi sinar matahari. Sepanjang jalur kebun raya Anda sampai pada suatu area, dimana jalurnya terbagi menjadi dua, memanjang hingga ke dalam hutan lebat...",
		talkContent_en = "The botanical garden is full of strange plants, and the lush foliage shades the sun. Along the path of the botanical garden you come to a area, where the path is divided into two, extending into the dense forest...",
		talkContent = "The botanical garden is full of strange plants, and the lush foliage shades the sun. Along the path of the botanical garden you come to a area, where the path is divided into two, extending into the dense forest..."
