		talkContent_id = " Anda datang ke pulau kedua. Menurut panduan ekspedisi, petunjuk lainnya ada di Igloo di tengah pulau es. Daerah sekitarnya berwarna putih. Es tebal dan salju menghalangi pandangan Anda. Misty secara tidak sengaja menginjak perangkap es yang dipasang oleh Weavile...",
		talkContent_en = "You come to the second island. According to the expedition manual, another clue is in the Igloo at the center of the ice island. The surrounding area is white. Thick ice and snow hinder your sight. Misty accidentally stepped on the ice trap set by Weavile...",
