	[100301] = {
		id = 100301,
		lastTime = 2000,
		talkContent_th = "หลังจากพลิกผันบ้างแล้ว คุณก็มุ่งหน้าไปยังเกาะที่สี่ เมื่ออยู่ใกล้เกาะก็สัมผัสได้ถึงอากาศที่ร้อนอบอ้าว จากระยะไกลภูเขาไฟที่ใจกลางเกาะมีลาวาที่ปกคลุมไปด้วยควันสีดำเป็นลูกคลื่น และ  Charizard ลอยอยู่บนท้องฟ้า ดูเหมือนจะต้อนรับการมาถึงของคุณ...",
		talkContent_id = "Setelah beberapa tikungan dan belokan, Anda menuju ke pulau keempat. Saat sudah dekat dengan pulau ini, udara panas sudah terasa. Dari kejauhan, gunung berapi di tengah pulau ini mengalirkan lahar, diselimuti asap hitam yang mengepul, dan Charizard yang melayang di angkasa, seolah menyambut kedatangan Anda...",
		talkContent_en = "After some twists and turns, you head to the fourth island. When you are close to the island, you have already felt the hot air. From a distance, the volcano in the center of the island is flowing with lava, engulfed in billowing black smoke, and Charizard hovering at sky, it seems to be welcoming your arrival...",
		talkContent = "After some twists and turns, you head to the fourth island. When you are close to the island, you have already felt the hot air. From a distance, the volcano in the center of the island is flowing with lava, engulfed in billowing black smoke, and Charizard hovering at sky, it seems to be welcoming your arrival..."
	},
