	[100401] = {
		id = 100401,
		lastTime = 2000,
		talkContent_th = "ออกจากเกาะแห่งไฟ คุณมาที่เบาะแสต่อไป ตามคำอธิบายของคู่มือ เกาะในจินตนาการนี้จริง ๆ แล้วเป็นภาพลวงตาทางวิญญาณที่สร้างขึ้นโดย  Alakazam บนเกาะมีการ์เดี้ยนตัวจริงเพียงคนเดียวเท่านั้น ที่เหลือทั้งหมดเป็นร่างโคลนของ  Alakazam ถ้าคุณต้องการผ่านการทดสอบ คุณต้องหาตัวจริงให้เร็วที่สุด...",
		talkContent_id = " Meninggalkan Pulau Api, Anda sampai pada petunjuk berikutnya. Menurut deskripsi manual, pulau fantasi ini sebenarnya adalah ilusi spiritual yang diciptakan oleh Alakazam. Sebenarnya hanya ada satu penjaga asli di pulau itu, dan sisanya adalah klon hantu Alakazam, jika ingin lulus ujian, kamu harus menemukan yang asli secepatnya...",
		talkContent_en = "Leaving the Fire Island, you came to the next clue. According to the description of manual, this fantasy island is actually a spiritual illusion created by Alakazam. There is actually only one real guardian on the island, and the rest are all Alakazam’s phantom clone, if you want to pass the test, you must find the true one as soon as possible...",
		talkContent = "Leaving the Fire Island, you came to the next clue. According to the description of manual, this fantasy island is actually a spiritual illusion created by Alakazam. There is actually only one real guardian on the island, and the rest are all Alakazam’s phantom clone, if you want to pass the test, you must find the true one as soon as possible..."
	},
	[100403] = {
