		lastTime = 2000,
		talkContent_th = "หลังจากผ่านการทดสอบ  Alakazam คุณจะได้กระดานชนวนสีม่วงที่วาดด้วยลวดลาย  Machamp",
		talkContent_id = " Setelah lulus ujian Alakazam, Anda mendapatkan batu ungu yang dicat dengan pola Machamp.",
		talkContent_en = "After passing the test of Alakazam, you got a purple slate painted with Machamp patterns.",
		talkContent = "After passing the test of Alakazam, you got a purple slate painted with Machamp patterns."
