	[100501] = {
		id = 100501,
		lastTime = 2000,
		talkContent_th = "ในที่สุดก็ไขปริศนาภาพลวงตาของ  Alakazam ได้แล้ว คุณได้เร่งฝีเท้าของคุณ คุณมาที่หน้าชิงช้าสวรรค์ คู่มือบอกคุณว่าเบาะแสถูกซ่อนอยู่ในห้องนักบิน แต่คนเดียวที่รู้ตำแหน่งของเบาะแสคือ  Hoopa คุณต้องแยกแยะเขาอย่างระมัดระวัง อย่าหลงกลเขา...",
		talkContent_id = "Akhirnya terpecahkan misteri ilusi Alakazam. Anda telah mempercepat langkah Anda. Anda datang di depan bianglala. Manual memberitahu Anda bahwa petunjuk tersebut tersembunyi di salah satu kokpit, tetapi satu-satunya orang yang mengetahui lokasi spesifik dari petunjuk tersebut adalah Hoopa. Anda harus membedakannya dengan hati-hati. Jangan tertipu olehnya...",
		talkContent_en = "Finally solved the mystery of Alakazam‘s illusion. You have quickened your pace. You came in front of a Ferris wheel. The manual tells you that the clue is hidden in one of the cockpits, but the only person who knows the specific location of the clue is Hoopa.You must distinguish him carefully. Don’t be fooled by him...",
		talkContent = "Finally solved the mystery of Alakazam‘s illusion. You have quickened your pace. You came in front of a Ferris wheel. The manual tells you that the clue is hidden in one of the cockpits, but the only person who knows the specific location of the clue is Hoopa.You must distinguish him carefully. Don’t be fooled by him..."
	},
