	[100616] = {
		id = 100616,
		lastTime = 2000,
		talkContent_th = "หลังจากขับเจ้าแบดบอยได้สำเร็จและรักษาอาการบาดเจ็บของ  Feebas ได้สำเร็จ  Feebas ก็รู้สึกขอบคุณคุณมาก ดังนั้นคุณจึงตัดสินใจนำมันไปที่โปเกบอลก่อน แล้วจึงค่อยเข้ารับการรักษาเพิ่มเติมหลังจากการสำรวจสิ้นสุดลง ตอนของการช่วยชีวิต  Feebas ได้จบลงแล้ว คุณเก็บของแล้วมุ่งหน้าไปยังดินแดนขุมทรัพย์ที่ทำเครื่องหมายไว้บนแผ่นหิน...",
		talkContent_id = " Setelah berhasil mengusir bocah nakal itu dan menstabilkan cedera Feebas, Feebas sangat berterima kasih kepada Anda, jadi Anda memutuskan untuk membawanya ke Poke Ball terlebih dahulu, dan kemudian mendapatkan perawatan lebih lanjut setelah ekspedisi selesai. Episode penyelamatan Feebas telah berakhir. Anda berkemas dan terus bergerak menuju tanah harta karun yang ditandai di lempengan batu ...",
		talkContent_en = "After successfully driving off the bad boy and stabilizing Feebas's injury, Feebas is very grateful to you, so you decide to take it into the Poke Ball first, and then gets further treatment after the expedition is over. The episode of rescuing Feebas has come to an end. You packed up and continue to move towards the treasure land marked on the stone slab...",
		talkContent = "After successfully driving off the bad boy and stabilizing Feebas's injury, Feebas is very grateful to you, so you decide to take it into the Poke Ball first, and then gets further treatment after the expedition is over. The episode of rescuing Feebas has come to an end. You packed up and continue to move towards the treasure land marked on the stone slab..."
	},
	[100701] = {
		id = 100701,
		lastTime = 2000,
		talkContent_th = "ในที่สุดคุณก็มาถึงที่ที่มีกระดานชนวน แต่มีทะเลทรายอยู่รอบๆ ที่นี่ และดูเหมือนไม่มีสิ่งปลูกสร้างเลย ที่แปลกที่สุดคือมีเสาสีต่างกันหกต้นตั้งตระหง่านอยู่กลางทะเลทราย สีเหล่านี้ทำให้คุณคุ้นเคย...",
		talkContent_id = "Anda akhirnya sampai di tempat yang ditandai dengan batu tulis, tetapi ada gurun di sekitar sini, dan sepertinya tidak ada bangunan sama sekali. Yang paling aneh adalah ada enam pilar dengan warna berbeda berdiri di tengah gurun pasir. Warna-warna ini membuat Anda merasa familiar dengannya...",
		talkContent_en = "You finally came to the place marked by the slate, but there is a desert all around here, and it doesn’t look like there are buildings at all. The strangest thing is that there are six pillars of different colors standing in the middle of the desert. These colors make you feel familiar to it...",
