	[100703] = {
		id = 100703,
		lastTime = 2000,
		talkContent_th = "หลังจากไขปริศนาการก่อตัวของหินได้สำเร็จ โลกก็เริ่มสั่นสะท้าน บางสิ่งค่อยๆ ผุดขึ้นจากทราย ผ่านไปครู่หนึ่ง โพรงหินเตี้ย ๆ ก็ปรากฏขึ้นต่อหน้าคุณ และรูปปั้นที่สวยงามของ  Milotic ถูกวางไว้ในช่องหิน ดูเหมือนว่าจะมีบางอย่างบนรูปปั้นที่ส่องแสงเจิดจ้าภายใต้ดวงอาทิตย์...",
		talkContent_id = " Setelah berhasil memecahkan teka-teki pembentukan batu , bumi mulai bergetar. Sesuatu secara bertahap muncul dari pasir. Beberapa saat kemudian, sebuah ceruk batu  rendah muncul di hadapan Anda, dan sebuah patung Milotic yang cantik ditempatkan di dalam ceruk batu  tersebut, sepertinya ada sesuatu pada patung itu yang bersinar terang di bawah sinar matahari...",
		talkContent_en = "After successfully solving the puzzle of the stone formation, the earth began to tremble. Something gradually rose from the sand. After a while, a low stone niche appeared in front of you, and a beautiful statue of Milotic was placed in the stone niche, there seems to be something on the statue shining brightly under the sun...",
		talkContent = "After successfully solving the puzzle of the stone formation, the earth began to tremble. Something gradually rose from the sand. After a while, a low stone niche appeared in front of you, and a beautiful statue of Milotic was placed in the stone niche, there seems to be something on the statue shining brightly under the sun..."
	},
	[100801] = {
		id = 100801,
		lastTime = 2000,
		talkContent_th = "ขณะที่คุณกำลังจะขึ้นรูปปั้น เงาสีดำโอบล้อมคุณราวกับว่าดวงอาทิตย์ถูกบางสิ่งบังไว้ เมื่อคุณมองขึ้นไป มันคือเรือเหาะขนาดใหญ่ เมื่อคุณแหงนมองท้องฟ้า แขนหุ่นยนต์ก็เป็นผู้นำ รูปปั้นของ  Milotic ถูกหยิบขึ้นมาจากช่องหินและหดกลับเข้าไปในเรือเหาะอย่างรวดเร็ว",
		talkContent_id = " Saat Anda hendak mengambil patung itu, bayangan hitam menyelimuti Anda, seolah matahari terhalang oleh sesuatu. Ketika Anda melihat ke atas, itu adalah sebuah pesawat besar. Saat Anda melihat ke langit, sebuah lengan robot memimpin. Patung Milotic diambil dari ceruk batu  dan segera dimasukkan ke dalam pesawat.",
		talkContent_en = "Just as you were about to take the statue, a black shadow enveloped you, as if the sun was blocked by something. When you looked up, it was a huge airship. Just when you looked up at the sky, a robotic arm took the lead. The statue of Milotic was picked up from the stone niche and quickly retracted into the airship.",
		talkContent = "Just as you were about to take the statue, a black shadow enveloped you, as if the sun was blocked by something. When you looked up, it was a huge airship. Just when you looked up at the sky, a robotic arm took the lead. The statue of Milotic was picked up from the stone niche and quickly retracted into the airship."
	},
