		talkContent_id = " Kecelakaan itu terjadi terlalu cepat, rekan Anda di pesawat luar angkasa mengirimkan Pokémon untuk membantu dengan tergesa-gesa, tetapi karena perbedaan ketinggian, Anda akan jatuh ke dalam danau...",
