	[400001] = {
		id = 400001,
		lastTime = 2000,
		talkContent_th = "It's the summer festival of the new year again, and you are planning to go to the beautiful summer island for vacation. Accidentally, you heard from a TV commercial that a Scalchop King Battle is hosting on Scalchop Island. Only trainers with an Oshawott can participate, so go to the Doctor's Research Institute and get an Oshawott!",
		talkContent_id = "Ini adalah festival musim panas tahun baru lagi, dan Anda berencana pergi ke pulau musim panas yang indah untuk berlibur. Secara tidak sengaja, Anda mendengar dari iklan TV bahwa Scalchop King Battle diadakan di Pulau Scalchop. Hanya trainer dengan Oshawott yang dapat berpartisipasi, jadi pergilah ke Institut Penelitian Dokter dan dapatkan Oshawott!",
		talkContent_en = "It's the summer festival of the new year again, and you are planning to go to the beautiful summer island for vacation. Accidentally, you heard from a TV commercial that a Scalchop King Battle is hosting on Scalchop Island. Only trainers with an Oshawott can participate, so go to the Doctor's Research Institute and get an Oshawott!",
		talkContent = "It's the summer festival of the new year again, and you are planning to go to the beautiful summer island for vacation. Accidentally, you heard from a TV commercial that a Scalchop King Battle is hosting on Scalchop Island. Only trainers with an Oshawott can participate, so go to the Doctor's Research Institute and get an Oshawott!"
	},
	[400101] = {
		id = 400101,
		lastTime = 2000,
		talkContent_th = "You brought Oshawott to the tournament scene. Oshawott fell in love with Osharina, the queen of Scalcshop, at first sight. Unexpectedly, Osharina not only ignored Oshawott, but also thrown amorous glances at Dewott. Oshawott was very angry and challenged its rival.",
		talkContent_id = " Anda membawa Oshawott ke kancah turnamen. Oshawott jatuh cinta pada Osharina, ratu Scalcshop, pada pandangan pertama. Tak disangka, Osharina tak hanya mengabaikan Oshawott, tapi juga melirik Dewott dengan penuh cinta. Oshawott sangat marah dan menantang saingannya.",
		talkContent_en = "You brought Oshawott to the tournament scene. Oshawott fell in love with Osharina, the queen of Scalcshop, at first sight. Unexpectedly, Osharina not only ignored Oshawott, but also thrown amorous glances at Dewott. Oshawott was very angry and challenged its rival.",
		talkContent = "You brought Oshawott to the tournament scene. Oshawott fell in love with Osharina, the queen of Scalcshop, at first sight. Unexpectedly, Osharina not only ignored Oshawott, but also thrown amorous glances at Dewott. Oshawott was very angry and challenged its rival."
	},
	[400102] = {
		lastTime = 2000,
		talkContent_en = "Choose one effect for Oshawott and Dewott will get the remaining two",
		talkContent_th = "Choose one effect for Oshawott and Dewott will get the remaining two",
		id = 400102,
		talkContent = "Choose one effect for Oshawott and Dewott will get the remaining two",
		talkContent_id = "Pilih satu efek untuk Oshawott dan Dewott akan mendapatkan dua sisanya",
		choices = {
			400101,
			400102,
			400103
		}
	},
	[400201] = {
		id = 400201,
		lastTime = 2000,
		talkContent_th = "Oshawott was very disappointed with loss to Dewott, so you decided to special train Oshawott to win the final Scalchop King Battle. The first exercise is tightrope walking, Oshawott needs to maintain his balance and not fall to the ground",
		talkContent_id = " Oshawott sangat kecewa dengan kekalahan dari Dewott, jadi Anda memutuskan untuk melatih Oshawott secara khusus untuk memenangkan Pertempuran Raja Scalchop terakhir. Latihan pertama adalah jalan di atas tali, Oshawott perlu menjaga keseimbangan dan tidak jatuh ke tanah",
		talkContent_en = "Oshawott was very disappointed with loss to Dewott, so you decided to special train Oshawott to win the final Scalchop King Battle. The first exercise is tightrope walking, Oshawott needs to maintain his balance and not fall to the ground",
		talkContent = "Oshawott was very disappointed with loss to Dewott, so you decided to special train Oshawott to win the final Scalchop King Battle. The first exercise is tightrope walking, Oshawott needs to maintain his balance and not fall to the ground"
	},
	[400301] = {
		id = 400301,
		lastTime = 2000,
		talkContent_th = "The second special training content is dodgeball training, exercise Oshawott's agility. If Oshawott is hit three times by the ball, it will be out of the game",
		talkContent_id = " Isi latihan khusus yang kedua adalah latihan dodgeball, melatih ketangkasan Oshawott. Jika Oshawott terkena bola sebanyak tiga kali, ia akan keluar dari permainan",
		talkContent_en = "The second special training content is dodgeball training, exercise Oshawott's agility. If Oshawott is hit three times by the ball, it will be out of the game",
		talkContent = "The second special training content is dodgeball training, exercise Oshawott's agility. If Oshawott is hit three times by the ball, it will be out of the game"
	},
